package com.crm.crm.controller;
import com.crm.crm.entity.*; import com.crm.crm.service.*; import org.springframework.stereotype.Controller; import org.springframework.ui.Model; import org.springframework.web.bind.annotation.GetMapping;
@Controller public class DashboardController {private final ClientService c; private final LeadService l; private final TaskService t; private final InteractionService i; public DashboardController(ClientService c,LeadService l,TaskService t,InteractionService i){this.c=c;this.l=l;this.t=t;this.i=i;} @GetMapping("/dashboard") public String dashboard(Model m){m.addAttribute("clientCount",c.count());m.addAttribute("leadCount",l.count());m.addAttribute("newLeadCount",l.count(LeadStatus.NEW));m.addAttribute("pendingTaskCount",t.count(TaskStatus.PENDING));m.addAttribute("interactionCount",i.count());return "dashboard";}}
